  "셋째, 결정 사항이 아닌 인사말, 질문, 의견, 보고는 절대로 포함하지 마십시오. 넷째, 결정 사항은 발언에 나온 문장을 고치지 말고 그대로 옮겨 주십시오.\n" +
  "다섯째, 결정 사항이 하나도 없으면 없다고만 답해 주십시오. 여섯째, 답은 한국어로, 한 줄에 하나씩 적어 주십시오.\n" +
  "다시 한번 강조합니다. 결정 사항만 골라 주시고, 발언에 없는 내용은 절대로 지어내지 마십시오. 항상 정확하고 간결하게 답해 주시면 감사하겠습니다.\n" +
  "지금까지 요약한 내용이 있더라도 아래 발언을 처음부터 다시 읽고 결정 사항을 다시 정리해 주십시오.";
const SHORT_RULE = "발언에서 결정 사항만 그대로 골라 한 줄에 하나씩 적어 주세요.";
const PRICE = { server_sec: 0.4, in_1k: 4.0, out_1k: 16.0 }; // 가상의 단가(원): 서버 1초 · 입력 1,000토큰 · 출력 1,000토큰

function buildPromptsSlow(lines: string[]): string[] {
  // (레거시) 발언이 하나 늘 때마다 긴 지침과 지금까지의 발언 전부를 다시 보낸다
  const out: string[] = [];
  for (let k = 1; k <= lines.length; k++) out.push(RULES + "\n" + lines.slice(0, k).map((s) => "- " + s).join("\n"));
  return out;
}

function buildPromptsFast(lines: string[]): string[] {
  // (K5) 짧은 지침 한 줄 + 발언 전부, 한 번만. 발언은 줄마다 '- '로 시작해야 LLM이 알아본다
  return [SHORT_RULE + "\n" + lines.map((s) => "- " + s).join("\n")];
}

function countTokens(text: string): number {
  // 토큰 수의 근사: 한글 한 글자 · 영어 낱말 하나 · 숫자 하나 · 기호 하나를 1토큰으로 센다
  return (text.match(/[가-힣]|[A-Za-z]+|\d|[^\s\w]/gu) ?? []).length;
}

function llm(prompt: string): string {
  // LLM 흉내(규칙): '- '로 시작하는 발언 줄 가운데 '결정'이 들어 있는 줄을 그대로 돌려준다. 키도 인터넷도 쓰지 않는다
  tick("LLM 요약", "llm", countTokens(prompt) * 0.001);
  const hits = prompt.split("\n").filter((ln) => ln.startsWith("- ") && ln.replace(/ /g, "").includes("결정")).map((ln) => ln.slice(2).trim());
  return hits.length ? hits.join("\n") : "없음";
}

type Use = { calls: number; in: number; out: number };
function runLlm(prompts: string[], use: Use): string[] {
  // 프롬프트를 차례로 보내고 마지막 답을 돌려준다. 쓴 토큰을 use에 더한다
  let answer = "없음";
  for (const p of prompts) {
    answer = llm(p);
    use.calls += 1;
    use.in += countTokens(p);
    use.out += countTokens(answer);
  }
  return answer === "없음" ? [] : answer.split("\n");
}

type Todo = { who: string; due: string; what: string };
function findTodos(lines: string[]): Todo[] {
  // '○○○ 선생님(실장님)이 ○요일까지 … 주세요' 꼴의 발언에서 담당과 기한을 뽑는다
  tick("그 밖", "find_todos", lines.length * 0.5);
  const todos: Todo[] = [];
  for (const s of lines) {
    const t = s.replace(/ /g, "");
    const m = /([가-힣]{3})(선생님|실장님)이([월화수목금토일]요일)까지/.exec(t);
    if (m && t.includes("주세요")) todos.push({ who: m[1], due: m[3], what: t });
  }
  return todos;
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 편집 거리 / 정답 글자 수 (공백 · 기호는 뺀다)
  const r = ref.replace(/[^0-9A-Za-z가-힣]/g, "");
  const h = hyp.replace(/[^0-9A-Za-z가-힣]/g, "");
  const d = Array.from({ length: h.length + 1 }, (_, i) => i);
  for (let i = 1; i <= r.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= h.length; j++) {
      const cur = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (r[i - 1] !== h[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return d[h.length] / Math.max(1, r.length);
}

function identity<A, B>(fn: (a: A) => B): (a: A) => B {
  // (레거시) 아무것도 기억하지 않는다
  return fn;
}

function remember<B>(fn: (y: Float64Array) => B): (y: Float64Array) => B {
  // (K4) 소리의 '내용'으로 열쇠를 만들어, 같은 소리는 한 번만 계산한다
  const store = new Map<string, B>();
  return (y) => {
    const key = createHash("sha1").update(Buffer.from(Float64Array.from(y).buffer)).digest("hex");
    if (!store.has(key)) store.set(key, fn(y));
    return store.get(key) as B;
  };
}

type Stages = {
  frame_energy: (y: Float64Array) => number[];
  transcribe: (segs: Float64Array[]) => string[];
  remember: (fn: (y: Float64Array) => string[]) => (y: Float64Array) => string[];
  build_prompts: (lines: string[]) => string[];
};

function makeStages(cards: string[] = []): Stages {
  // 카드(K1~K5)를 켠 만큼만 새 함수를 끼우고, 나머지 자리는 레거시 함수가 맡는다
  const ga = cards.includes("K2") ? cachedLoader() : loadAsr;
  const trans = cards.includes("K3") ? transcribeFast : transcribeSlow;
  return {
    frame_energy: cards.includes("K1") ? frameEnergyFast : frameEnergySlow,
    transcribe: (segs) => trans(segs, ga),
    remember: cards.includes("K4") ? remember : identity,
    build_prompts: cards.includes("K5") ? buildPromptsFast : buildPromptsSlow,
  };
}

function makeMinutes(y: Float64Array, S: Stages, use: Use) {
  // 녹음 → 회의록. 결정 사항을 뽑으려고 한 번, 할 일을 뽑으려고 (처음부터) 한 번 더 듣는다
  const listen = S.remember((y: Float64Array) => S.transcribe(findSegments(S.frame_energy(y)).map(([a, b]) => y.slice(a, b))));
  const lines = listen(y);
  const decisions = runLlm(S.build_prompts(lines), use);
  const todos = findTodos(listen(y));
  return { lines, decisions, todos };
}

const STAGES = ["구간 찾기", "모델 올리기", "받아쓰기", "LLM 요약", "그 밖"];

function measure(y: Float64Array, cards: string[] = [], refText: string = REF_TEXT) {
  // 켠 카드로 회의록을 한 번 만들고 (가상) 시간 · 비용 · 정확도를 잰다
  if (!refText) throw new Error("정답 글이 비어 있으면 CER을 잴 수 없어요");
  for (const k of Object.keys(TICKS)) delete TICKS[k];
  for (const k of Object.keys(FN)) delete FN[k];
  const use: Use = { calls: 0, in: 0, out: 0 };
  const m = makeMinutes(y, makeStages(cards), use);
  const stages: Record<string, number> = {};
  for (const k of STAGES) stages[k] = TICKS[k] ?? 0;
  const sec = Object.values(stages).reduce((a, b) => a + b, 0) / 1000;
  const server = sec * PRICE.server_sec;
  const tok = (use.in / 1000) * PRICE.in_1k + (use.out / 1000) * PRICE.out_1k;
  return {
    sec, stages, loads: FN["load_asr"]?.[0] ?? 0, calls: use.calls, tok_in: use.in, tok_out: use.out,
    cost_server: server, cost_llm: tok, cost: server + tok, cer: cer(refText, m.lines.join("")),
    n_dec: m.decisions.length, n_todo: m.todos.length, minutes: m, audio_sec: y.length / SR,
  };
}

// ── 암달의 법칙: p = 그 단계의 비중(0~1), s = 그 단계가 빨라진 배수 → 전체가 빨라지는 배수 ──
function amdahl(p: number, s: number): number {
  if (!(p >= 0 && p <= 1)) throw new Error("비중 p는 0 ~ 1 사이여야 해요");
  if (!(s > 0)) throw new Error("배수 s는 0보다 커야 해요");
  return 1 / (1 - p + p / s);
}

function limit(p: number): number {
  // s가 무한대일 때(그 단계가 0초가 돼도) 전체가 빨라지는 한계 = 1 / (1 - p)
  if (!(p >= 0 && p < 1)) throw new Error("한계는 p < 1 일 때만 있어요");
  return 1 / (1 - p);
}

const raises = (fn: () => unknown): boolean => {
  try {
    fn();
  } catch {
    return true;
  }
  return false;
};

const base = measure(Y);
console.log("단계 · 비중 · 이 단계만 10배 빨라지면 전체는 · 0초가 돼도 전체는(한계)");
for (const [k, v] of Object.entries(base.stages)) {
  const p = v / base.sec / 1000;
  console.log(`  ${k.padEnd(8)} ${(p * 100).toFixed(1).padStart(5)}%  ×${amdahl(p, 10).toFixed(2)}  ` + (p < 0.999 ? `×${limit(p).toFixed(2)}` : "-"));
}

// 예측(암달)과 실제 측정을 맞춰 본다: 카드 하나만 켜고, 그 카드가 줄인 단계의 배수를 재서 전체 배수를 예측한다
function predictVsMeasure(card: string, stage: string): [number, number, number, number] {
  const r = measure(Y, [card]);
  const p = base.stages[stage] / (base.sec * 1000);
  const s = base.stages[stage] / r.stages[stage]; // 그 단계가 실제로 빨라진 배수
  return [p, s, amdahl(p, s), base.sec / r.sec];
}

const [p1, s1, pred1, got1] = predictVsMeasure("K1", "구간 찾기"); // 이중 반복문을 고친 카드
const [p2, s2, pred2, got2] = predictVsMeasure("K2", "모델 올리기"); // 모델을 한 번만 올리는 카드
console.log(`K1 구간 찾기: 비중 ${(p1 * 100).toFixed(1)}% · 단계는 ×${s1.toFixed(0)} · 전체 예측 ×${pred1.toFixed(3)} · 실제 ×${got1.toFixed(3)} (한계 ×${limit(p1).toFixed(3)})`);
console.log(`K2 모델 올리기: 비중 ${(p2 * 100).toFixed(1)}% · 단계는 ×${s2.toFixed(0)} · 전체 예측 ×${pred2.toFixed(3)} · 실제 ×${got2.toFixed(3)} (한계 ×${limit(p2).toFixed(3)})`);

const okFormula = Math.abs(amdahl(0.5, 2) - 4 / 3) < 1e-9 && amdahl(0.01, 100) > 1 && amdahl(0.01, 100) < 1.011 && Math.abs(amdahl(1.0, 7) - 7) < 1e-12 && amdahl(0.0, 7) === 1;
const okErrors = raises(() => amdahl(1.5, 2)) && raises(() => amdahl(-0.1, 2)) && raises(() => amdahl(0.5, 0)) && raises(() => limit(1.0));
const okPredict = Math.abs(pred1 - got1) < 1e-9 && Math.abs(pred2 - got2) < 1e-9; // 예측과 실제가 같다
const okTrap = s1 > 40 && got1 < 1.02 && got2 > 2 && got1 < limit(p1) && got2 < limit(p2); // 50배 빨라진 단계도 전체는 거의 그대로, 큰 덩어리가 이긴다
check(okFormula && okErrors && okPredict && okTrap, "예측(암달)과 실제 측정이 같아야 하고, 비중 1% 미만인 구간 찾기는 50배 빨라져도 전체는 1.02배 미만이어야 해요.");

batch.typescript:
// D47 · 모델과 배치 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d47_batch.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델 · LLM은 쓰지 않고 규칙과 가상 시계로 흉내)
//   모델은 한 번만 올리고 조각은 한꺼번에 받아쓰기 (작은 모델 int8 · 정확도는 다시 잼)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const SR = 16000;
const FRAME = 320; // 20 ms
const REF: string[] = [ // 회의 발언 14개 (정답 글). 결정 3개 · 할 일 3개가 들어 있음
  "안녕하세요 오늘 회의를 시작하겠습니다",
  "지난주 예약 취소가 열두 건 있었습니다",
  "그래서 예약 확인 문자를 하루 전에 보내기로 결정했습니다",
  "김하나 실장님이 금요일까지 문자 문구를 정리해 주세요",
  "접수 대기 시간이 길다는 의견이 있었습니다",
  "점심시간 접수는 한 명이 맡기로 결정했습니다",
  "박지훈 선생님이 수요일까지 교대표를 만들어 주세요",
  "스케일링 재료 재고는 충분합니다",
  "소독기 점검 일정은 아직 잡히지 않았습니다",
  "토요일 진료는 오후 한 시까지로 결정했습니다",
  "이서연 선생님이 목요일까지 안내문을 인쇄해 주세요",
  "환자 불만은 줄어드는 추세입니다",
  "다른 의견 있으신가요",
  "그럼 오늘 회의는 여기서 마치겠습니다",
];
const REF_TEXT = REF.join(""); // 채점용 정답 글

function makeAudio(): Float64Array {
  // 발언 14개를 사인파 토막으로 만든 녹음. 토막의 소리 크기가 몇 번째 발언인지를 알려 준다. 발언 사이는 0.7초 무음
  const gap = Math.floor((SR * 7) / 10);
  const parts: number[] = new Array(gap).fill(0);
  for (let k = 0; k < REF.length; k++) {
    const frames = 15 + ((k * 5) % 8); // 한 발언은 15 ~ 22조각 (0.3 ~ 0.44초)
    const amp = 0.1 + 0.02 * k;
    for (let n = 0; n < frames * FRAME; n++) parts.push(amp * Math.sin((Math.PI * n) / 16));
    for (let n = 0; n < gap; n++) parts.push(0);
  }
  return Float64Array.from(parts);
}
const Y = makeAudio();

const TICKS: Record<string, number> = {}; // 가상 시계: 단계별로 쌓인 ms (실제 시간이 아니라 작업량이라 컴퓨터가 달라도 같음)
const FN: Record<string, [number, number]> = {}; // 함수별 [부른 횟수, 쌓인 ms]

function tick(stage: string, fn: string, ms: number): void {
  TICKS[stage] = (TICKS[stage] ?? 0) + ms;
  const rec = (FN[fn] ??= [0, 0]);
  rec[0] += 1;
  rec[1] += ms;
}

function frameEnergySlow(y: Float64Array): number[] {
  // (레거시) 20 ms 조각마다 소리의 크기(RMS)를 잰다. 표본을 하나씩 더한다
  const out: number[] = [];
  for (let i = 0; i < Math.floor(y.length / FRAME); i++) {
    let total = 0;
    for (let j = 0; j < FRAME; j++) total += y[i * FRAME + j] ** 2;
    out.push(Math.sqrt(total / FRAME));
  }
  tick("구간 찾기", "frame_energy", y.length * 0.001);
  return out;
}

function frameEnergyFast(y: Float64Array): number[] {
  // (K1) 조각 단위로 한꺼번에 계산. 속도 차이는 가상 시계(50배 빠름)로 흉내 낸다
  const n = Math.floor(y.length / FRAME);
  const out: number[] = [];
  for (let i = 0; i < n; i++) out.push(Math.sqrt(y.slice(i * FRAME, (i + 1) * FRAME).reduce((a, v) => a + v * v, 0) / FRAME));
  tick("구간 찾기", "frame_energy", y.length * 0.00002);
  return out;
}

function findSegments(energy: number[], thr = 0.02, minSil = 25, pad = 5): [number, number][] {
  // 크기가 thr를 넘는 조각을 잇고, 0.5초(25조각) 넘게 조용하면 발언을 끊는다. → [(시작 표본, 끝 표본)]
  const spans: [number, number][] = [];
  let start: number | null = null;
  let quiet = 0;
  const e2 = [...energy, ...new Array(minSil + 1).fill(0)];
  for (let i = 0; i < e2.length; i++) {
    if (e2[i] > thr) {
      if (start === null) start = i;
      quiet = 0;
    } else if (start !== null) {
      quiet += 1;
      if (quiet > minSil) {
        spans.push([Math.max(0, start - pad) * FRAME, (i - quiet + 1 + pad) * FRAME]);
        start = null;
        quiet = 0;
      }
    }
  }
  return spans;
}

const LOAD_MS: Record<string, number> = { fp32: 1700, int8: 1100 }; // 모델 올리는 비용 (가상 ms)
const PER_SAMPLE_MS: Record<string, number> = { fp32: 0.025, int8: 0.012 }; // 소리 표본 하나를 받아쓰는 비용: int8이 더 싸다
const CALL_MS = 100; // decode를 한 번 부르는 고정 비용
const BATCH_FACTOR = 0.6; // 여러 조각을 한꺼번에 계산하면 조각당 비용이 줄어든다
const INT8_SLIP: Record<number, [string, string]> = { 9: ["습니다", "슴니다"] }; // 작은 모델(int8)이 한 글자를 잘못 들음 (정확도와 속도의 맞바꿈)

class Asr {
  // 받아쓰기 모델 흉내. 토막의 소리 크기로 몇 번째 발언인지 알아내 그 글을 돌려준다
  kind: string;
  constructor(kind: string) {
    this.kind = kind;
  }
  decode(segs: Float64Array[]): string[] {
    // 조각 여러 개 → 글 여러 개 (한 번 부르기)
    const pad = Math.floor(SR / 2) + Math.floor(SR * 0.8); // 앞 0.5초 · 뒤 0.8초 무음을 붙여 넣음
    const factor = segs.length === 1 ? 1.0 : BATCH_FACTOR;
    let ms = CALL_MS;
    for (const s of segs) ms += (s.length + pad) * PER_SAMPLE_MS[this.kind] * factor;
    tick("받아쓰기", "decode", ms);
    return segs.map((s) => {
      let peak = 0;
      for (const v of s) peak = Math.max(peak, Math.abs(v));
      const k = s.length ? Math.round((peak - 0.1) / 0.02) : -1;
      let text = k >= 0 && k < REF.length ? REF[k] : "";
      if (this.kind === "int8" && Object.hasOwn(INT8_SLIP, k)) text = text.replace(INT8_SLIP[k][0], INT8_SLIP[k][1]);
      return text;
    });
  }
}

function loadAsr(kind: string = "fp32"): Asr {
  // 받아쓰기 모델을 메모리에 올린다. 올릴 때마다 비용이 든다
  if (!Object.hasOwn(LOAD_MS, kind)) throw new Error(`kind는 fp32 또는 int8: ${kind}`);
  tick("모델 올리기", "load_asr", LOAD_MS[kind]);
  return new Asr(kind);
}

const decodeOne = (asr: Asr, y: Float64Array): string => asr.decode([y])[0];

function cachedLoader(): (kind?: string) => Asr {
  // (K2) 같은 kind는 한 번만 올린다. kind마다 따로 넣어 둔다
  const cache = new Map<string, Asr>();
  return (kind: string = "fp32") => {
    if (!cache.has(kind)) cache.set(kind, loadAsr(kind));
    return cache.get(kind) as Asr;
  };
}

function transcribeSlow(segs: Float64Array[], getAsr: (kind?: string) => Asr = loadAsr): string[] {
  // (레거시) 조각마다 모델을 준비하고 한 조각씩 받아쓴다
  return segs.map((seg) => decodeOne(getAsr("fp32"), seg));
}

function transcribeFast(segs: Float64Array[], getAsr: (kind?: string) => Asr): string[] {
  // (K3) 작은 모델(int8)로 모든 조각을 한꺼번에
  return getAsr("int8").decode([...segs]);
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 편집 거리 / 정답 글자 수 (공백 · 기호는 뺀다)
  const r = ref.replace(/[^0-9A-Za-z가-힣]/g, "");
  const h = hyp.replace(/[^0-9A-Za-z가-힣]/g, "");
  const d = Array.from({ length: h.length + 1 }, (_, i) => i);
  for (let i = 1; i <= r.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= h.length; j++) {
      const cur = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (r[i - 1] !== h[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return d[h.length] / Math.max(1, r.length);
}

// ── 모델은 한 번만 올리고, 작은 모델(int8)로, 조각은 한꺼번에 받아쓰기 ──
function reset(): void {
  for (const k of Object.keys(TICKS)) delete TICKS[k];
  for (const k of Object.keys(FN)) delete FN[k];
}
const total = (): number => Object.values(TICKS).reduce((a, b) => a + b, 0);
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)
const raises = (fn: () => unknown): boolean => {
  try {
    fn();
  } catch {
    return true;
  }
  return false;
};

const segs = findSegments(frameEnergyFast(Y)).map(([a, b]) => Y.slice(a, b)); // 발언 조각
console.log(`발언 조각 ${segs.length}개 (정답 글 ${REF.length}줄)`);

// 1) 모델은 한 번만: 같은 kind는 같은 모델, kind가 다르면 다른 모델 (열쇠를 나누지 않으면 int8을 달라는데 fp32가 나오는 버그)
reset();
const get = cachedLoader();
const [a, b, c, d] = [get("int8"), get("int8"), get("fp32"), get("fp32")];
const loads = FN["load_asr"][0];
console.log(`네 번 불렀는데 올린 모델은 ${loads}개 · int8 ${LOAD_MS.int8} < fp32 ${LOAD_MS.fp32} (가상 ms)`);
const okCache = a === b && c === d && a !== c && a.kind === "int8" && c.kind === "fp32" && loads === 2;
const okKind = ["fp16", "constructor", "__proto__", "toString", ""].every((k) => raises(() => loadAsr(k)) && raises(() => get(k))); // 모르는 kind는 조용히 넘어가지 않고 오류 (객체의 상속 속성 이름도)

// 작은 모델이 정말 싼지: 상수끼리 비교하지 않고, 실제로 올려 보며 늘어난 (가상) 시간을 잰다
function loadMs(kind: string): number {
  reset();
  loadAsr(kind);
  return total();
}
const [msInt8, msFp32] = [loadMs("int8"), loadMs("fp32")];
console.log(`모델 하나를 실제로 올릴 때 늘어난 시간: int8 ${msInt8.toFixed(0)} ms < fp32 ${msFp32.toFixed(0)} ms`);
const okSmall = msInt8 > 0 && msInt8 < msFp32;

// 2) 한 조각씩(레거시) 대 한꺼번에: 같은 모델이면 글이 같고 순서도 지켜진다
reset();
const slow = transcribeSlow(segs); // fp32 · 조각마다 모델을 다시 올림 · 한 조각씩
const [slowMs, slowCalls, slowLoads] = [total(), FN["decode"][0], FN["load_asr"][0]];
reset();
const fast = transcribeFast(segs, cachedLoader()); // int8 · 모델 한 번 · 한꺼번에
const [fastMs, fastCalls, fastLoads] = [total(), FN["decode"][0], FN["load_asr"][0]];
const oneByOne = segs.map((s) => decodeOne(get("int8"), s)); // 같은 int8 모델로 한 조각씩
console.log(`레거시: 모델 ${slowLoads}번 · decode ${slowCalls}번 · ${slowMs.toFixed(0)} ms → 묶음: 모델 ${fastLoads}번 · decode ${fastCalls}번 · ${fastMs.toFixed(0)} ms (×${(slowMs / fastMs).toFixed(1)})`);
const okSame = same(fast, oneByOne) && same(transcribeFast([...segs].reverse(), get), [...fast].reverse()) && same(transcribeFast([], get), []);
const okSpeed = slowLoads === segs.length && slowCalls === segs.length && fastLoads === 1 && fastCalls === 1 && fastMs < slowMs * 0.2;

// 3) 정확도는 다시 잰다: 레거시(fp32)는 정답과 같고, int8은 한 글자를 틀리지만 목표(+2%p) 안
const wrong = fast.map((x, i) => (x !== REF[i] ? i : -1)).filter((i) => i >= 0);
const [cerFp32, cerInt8] = [cer(REF_TEXT, slow.join("")), cer(REF_TEXT, fast.join(""))];
console.log(`CER fp32 ${(cerFp32 * 100).toFixed(2)}% · int8 ${(cerInt8 * 100).toFixed(2)}% · int8이 틀린 발언 ${JSON.stringify(wrong)}`);
const okAcc = REF.length === segs.length && segs.length === slow.length && slow.length === fast.length && same(slow, REF) &&
  same(wrong, Object.keys(INT8_SLIP).map(Number)) && cerInt8 - cerFp32 > 0 && cerInt8 - cerFp32 <= 0.02 && cer("가나다", "가다") === 1 / 3;

check(okCache && okKind && okSmall && okSame && okSpeed && okAcc, "같은 kind는 한 번만 올리고, 묶음 결과는 한 조각씩과 같고(순서 포함), 시간은 1/5 아래, int8의 CER은 레거시보다 0 초과 2%p 이하여야 해요.");

cache.typescript:
// D47 · 같은 일은 한 번만 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d47_cache.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델 · LLM은 쓰지 않고 규칙과 가상 시계로 흉내)
//   소리의 내용으로 열쇠를 만들어 같은 소리는 한 번만 계산 (캐시)
import { createHash } from "node:crypto";
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const SR = 16000;
const FRAME = 320; // 20 ms
const REF: string[] = [ // 회의 발언 14개 (정답 글). 결정 3개 · 할 일 3개가 들어 있음
  "안녕하세요 오늘 회의를 시작하겠습니다",
  "지난주 예약 취소가 열두 건 있었습니다",
  "그래서 예약 확인 문자를 하루 전에 보내기로 결정했습니다",
  "김하나 실장님이 금요일까지 문자 문구를 정리해 주세요",
  "접수 대기 시간이 길다는 의견이 있었습니다",
  "점심시간 접수는 한 명이 맡기로 결정했습니다",
  "박지훈 선생님이 수요일까지 교대표를 만들어 주세요",
  "스케일링 재료 재고는 충분합니다",
  "소독기 점검 일정은 아직 잡히지 않았습니다",
  "토요일 진료는 오후 한 시까지로 결정했습니다",
  "이서연 선생님이 목요일까지 안내문을 인쇄해 주세요",
  "환자 불만은 줄어드는 추세입니다",
  "다른 의견 있으신가요",
  "그럼 오늘 회의는 여기서 마치겠습니다",
];
const REF_TEXT = REF.join(""); // 채점용 정답 글

function makeAudio(): Float64Array {
  // 발언 14개를 사인파 토막으로 만든 녹음. 토막의 소리 크기가 몇 번째 발언인지를 알려 준다. 발언 사이는 0.7초 무음
  const gap = Math.floor((SR * 7) / 10);
  const parts: number[] = new Array(gap).fill(0);
  for (let k = 0; k < REF.length; k++) {
    const frames = 15 + ((k * 5) % 8); // 한 발언은 15 ~ 22조각 (0.3 ~ 0.44초)
    const amp = 0.1 + 0.02 * k;
    for (let n = 0; n < frames * FRAME; n++) parts.push(amp * Math.sin((Math.PI * n) / 16));
    for (let n = 0; n < gap; n++) parts.push(0);
  }
  return Float64Array.from(parts);
}
const Y = makeAudio();

const TICKS: Record<string, number> = {}; // 가상 시계: 단계별로 쌓인 ms (실제 시간이 아니라 작업량이라 컴퓨터가 달라도 같음)
const FN: Record<string, [number, number]> = {}; // 함수별 [부른 횟수, 쌓인 ms]

function tick(stage: string, fn: string, ms: number): void {
  TICKS[stage] = (TICKS[stage] ?? 0) + ms;
  const rec = (FN[fn] ??= [0, 0]);
  rec[0] += 1;
  rec[1] += ms;
}

function frameEnergySlow(y: Float64Array): number[] {
  // (레거시) 20 ms 조각마다 소리의 크기(RMS)를 잰다. 표본을 하나씩 더한다
  const out: number[] = [];
  for (let i = 0; i < Math.floor(y.length / FRAME); i++) {
    let total = 0;
    for (let j = 0; j < FRAME; j++) total += y[i * FRAME + j] ** 2;
    out.push(Math.sqrt(total / FRAME));
  }
  tick("구간 찾기", "frame_energy", y.length * 0.001);
  return out;
}

function frameEnergyFast(y: Float64Array): number[] {
  // (K1) 조각 단위로 한꺼번에 계산. 속도 차이는 가상 시계(50배 빠름)로 흉내 낸다
  const n = Math.floor(y.length / FRAME);
  const out: number[] = [];
  for (let i = 0; i < n; i++) out.push(Math.sqrt(y.slice(i * FRAME, (i + 1) * FRAME).reduce((a, v) => a + v * v, 0) / FRAME));
  tick("구간 찾기", "frame_energy", y.length * 0.00002);
  return out;
}

function findSegments(energy: number[], thr = 0.02, minSil = 25, pad = 5): [number, number][] {
  // 크기가 thr를 넘는 조각을 잇고, 0.5초(25조각) 넘게 조용하면 발언을 끊는다. → [(시작 표본, 끝 표본)]
  const spans: [number, number][] = [];
  let start: number | null = null;
  let quiet = 0;
  const e2 = [...energy, ...new Array(minSil + 1).fill(0)];
  for (let i = 0; i < e2.length; i++) {
    if (e2[i] > thr) {
      if (start === null) start = i;
      quiet = 0;
    } else if (start !== null) {
      quiet += 1;
      if (quiet > minSil) {
        spans.push([Math.max(0, start - pad) * FRAME, (i - quiet + 1 + pad) * FRAME]);
        start = null;
        quiet = 0;
      }
    }
  }
  return spans;
}

const LOAD_MS: Record<string, number> = { fp32: 1700, int8: 1100 }; // 모델 올리는 비용 (가상 ms)
const PER_SAMPLE_MS: Record<string, number> = { fp32: 0.025, int8: 0.012 }; // 소리 표본 하나를 받아쓰는 비용: int8이 더 싸다
const CALL_MS = 100; // decode를 한 번 부르는 고정 비용
const BATCH_FACTOR = 0.6; // 여러 조각을 한꺼번에 계산하면 조각당 비용이 줄어든다
const INT8_SLIP: Record<number, [string, string]> = { 9: ["습니다", "슴니다"] }; // 작은 모델(int8)이 한 글자를 잘못 들음 (정확도와 속도의 맞바꿈)

class Asr {
  // 받아쓰기 모델 흉내. 토막의 소리 크기로 몇 번째 발언인지 알아내 그 글을 돌려준다
  kind: string;
  constructor(kind: string) {
    this.kind = kind;
  }
  decode(segs: Float64Array[]): string[] {
    // 조각 여러 개 → 글 여러 개 (한 번 부르기)
    const pad = Math.floor(SR / 2) + Math.floor(SR * 0.8); // 앞 0.5초 · 뒤 0.8초 무음을 붙여 넣음
    const factor = segs.length === 1 ? 1.0 : BATCH_FACTOR;
    let ms = CALL_MS;
    for (const s of segs) ms += (s.length + pad) * PER_SAMPLE_MS[this.kind] * factor;
    tick("받아쓰기", "decode", ms);
    return segs.map((s) => {
      let peak = 0;
      for (const v of s) peak = Math.max(peak, Math.abs(v));
      const k = s.length ? Math.round((peak - 0.1) / 0.02) : -1;
      let text = k >= 0 && k < REF.length ? REF[k] : "";
      if (this.kind === "int8" && Object.hasOwn(INT8_SLIP, k)) text = text.replace(INT8_SLIP[k][0], INT8_SLIP[k][1]);
      return text;
    });
  }
}

function loadAsr(kind: string = "fp32"): Asr {
  // 받아쓰기 모델을 메모리에 올린다. 올릴 때마다 비용이 든다
  if (!Object.hasOwn(LOAD_MS, kind)) throw new Error(`kind는 fp32 또는 int8: ${kind}`);
  tick("모델 올리기", "load_asr", LOAD_MS[kind]);
  return new Asr(kind);
}

const decodeOne = (asr: Asr, y: Float64Array): string => asr.decode([y])[0];

function cachedLoader(): (kind?: string) => Asr {
  // (K2) 같은 kind는 한 번만 올린다. kind마다 따로 넣어 둔다
  const cache = new Map<string, Asr>();
  return (kind: string = "fp32") => {
    if (!cache.has(kind)) cache.set(kind, loadAsr(kind));
    return cache.get(kind) as Asr;
  };
}

function transcribeSlow(segs: Float64Array[], getAsr: (kind?: string) => Asr = loadAsr): string[] {
  // (레거시) 조각마다 모델을 준비하고 한 조각씩 받아쓴다
  return segs.map((seg) => decodeOne(getAsr("fp32"), seg));
}

function transcribeFast(segs: Float64Array[], getAsr: (kind?: string) => Asr): string[] {
  // (K3) 작은 모델(int8)로 모든 조각을 한꺼번에
  return getAsr("int8").decode([...segs]);
}

const RULES =
  "당신은 한빛치과의 회의록 작성을 돕는 매우 유능하고 친절한 인공지능 비서입니다. 아래의 지침을 하나도 빠짐없이 꼼꼼하게 읽고 반드시 지켜 주십시오.\n" +
  "첫째, 회의에서 나온 발언을 처음부터 끝까지 주의 깊게 읽어 주십시오. 둘째, 발언 가운데 무엇인가를 하기로 정한 결정 사항만 골라 주십시오.\n" +
  "셋째, 결정 사항이 아닌 인사말, 질문, 의견, 보고는 절대로 포함하지 마십시오. 넷째, 결정 사항은 발언에 나온 문장을 고치지 말고 그대로 옮겨 주십시오.\n" +
  "다섯째, 결정 사항이 하나도 없으면 없다고만 답해 주십시오. 여섯째, 답은 한국어로, 한 줄에 하나씩 적어 주십시오.\n" +
  "다시 한번 강조합니다. 결정 사항만 골라 주시고, 발언에 없는 내용은 절대로 지어내지 마십시오. 항상 정확하고 간결하게 답해 주시면 감사하겠습니다.\n" +
  "지금까지 요약한 내용이 있더라도 아래 발언을 처음부터 다시 읽고 결정 사항을 다시 정리해 주십시오.";
const SHORT_RULE = "발언에서 결정 사항만 그대로 골라 한 줄에 하나씩 적어 주세요.";
const PRICE = { server_sec: 0.4, in_1k: 4.0, out_1k: 16.0 }; // 가상의 단가(원): 서버 1초 · 입력 1,000토큰 · 출력 1,000토큰

function buildPromptsSlow(lines: string[]): string[] {
  // (레거시) 발언이 하나 늘 때마다 긴 지침과 지금까지의 발언 전부를 다시 보낸다
  const out: string[] = [];
  for (let k = 1; k <= lines.length; k++) out.push(RULES + "\n" + lines.slice(0, k).map((s) => "- " + s).join("\n"));
  return out;
}

function buildPromptsFast(lines: string[]): string[] {
  // (K5) 짧은 지침 한 줄 + 발언 전부, 한 번만. 발언은 줄마다 '- '로 시작해야 LLM이 알아본다
  return [SHORT_RULE + "\n" + lines.map((s) => "- " + s).join("\n")];
}

function countTokens(text: string): number {
  // 토큰 수의 근사: 한글 한 글자 · 영어 낱말 하나 · 숫자 하나 · 기호 하나를 1토큰으로 센다
  return (text.match(/[가-힣]|[A-Za-z]+|\d|[^\s\w]/gu) ?? []).length;
}

function llm(prompt: string): string {
  // LLM 흉내(규칙): '- '로 시작하는 발언 줄 가운데 '결정'이 들어 있는 줄을 그대로 돌려준다. 키도 인터넷도 쓰지 않는다
  tick("LLM 요약", "llm", countTokens(prompt) * 0.001);
  const hits = prompt.split("\n").filter((ln) => ln.startsWith("- ") && ln.replace(/ /g, "").includes("결정")).map((ln) => ln.slice(2).trim());
  return hits.length ? hits.join("\n") : "없음";
}

type Use = { calls: number; in: number; out: number };
function runLlm(prompts: string[], use: Use): string[] {
  // 프롬프트를 차례로 보내고 마지막 답을 돌려준다. 쓴 토큰을 use에 더한다
  let answer = "없음";
  for (const p of prompts) {
    answer = llm(p);
    use.calls += 1;
    use.in += countTokens(p);
    use.out += countTokens(answer);
  }
  return answer === "없음" ? [] : answer.split("\n");
}

type Todo = { who: string; due: string; what: string };
function findTodos(lines: string[]): Todo[] {
  // '○○○ 선생님(실장님)이 ○요일까지 … 주세요' 꼴의 발언에서 담당과 기한을 뽑는다
  tick("그 밖", "find_todos", lines.length * 0.5);
  const todos: Todo[] = [];
  for (const s of lines) {
    const t = s.replace(/ /g, "");
    const m = /([가-힣]{3})(선생님|실장님)이([월화수목금토일]요일)까지/.exec(t);
    if (m && t.includes("주세요")) todos.push({ who: m[1], due: m[3], what: t });
  }
  return todos;
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 편집 거리 / 정답 글자 수 (공백 · 기호는 뺀다)
  const r = ref.replace(/[^0-9A-Za-z가-힣]/g, "");
  const h = hyp.replace(/[^0-9A-Za-z가-힣]/g, "");
  const d = Array.from({ length: h.length + 1 }, (_, i) => i);
  for (let i = 1; i <= r.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= h.length; j++) {
      const cur = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (r[i - 1] !== h[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return d[h.length] / Math.max(1, r.length);
}

function identity<A, B>(fn: (a: A) => B): (a: A) => B {
  // (레거시) 아무것도 기억하지 않는다
  return fn;
}

function remember<B>(fn: (y: Float64Array) => B): (y: Float64Array) => B {
  // (K4) 소리의 '내용'으로 열쇠를 만들어, 같은 소리는 한 번만 계산한다
  const store = new Map<string, B>();
  return (y) => {
    const key = createHash("sha1").update(Buffer.from(Float64Array.from(y).buffer)).digest("hex");
    if (!store.has(key)) store.set(key, fn(y));
    return store.get(key) as B;
  };
}

type Stages = {
  frame_energy: (y: Float64Array) => number[];
  transcribe: (segs: Float64Array[]) => string[];
  remember: (fn: (y: Float64Array) => string[]) => (y: Float64Array) => string[];
  build_prompts: (lines: string[]) => string[];
};

function makeStages(cards: string[] = []): Stages {
  // 카드(K1~K5)를 켠 만큼만 새 함수를 끼우고, 나머지 자리는 레거시 함수가 맡는다
  const ga = cards.includes("K2") ? cachedLoader() : loadAsr;
  const trans = cards.includes("K3") ? transcribeFast : transcribeSlow;
  return {
    frame_energy: cards.includes("K1") ? frameEnergyFast : frameEnergySlow,
    transcribe: (segs) => trans(segs, ga),
    remember: cards.includes("K4") ? remember : identity,
    build_prompts: cards.includes("K5") ? buildPromptsFast : buildPromptsSlow,
  };
}

function makeMinutes(y: Float64Array, S: Stages, use: Use) {
  // 녹음 → 회의록. 결정 사항을 뽑으려고 한 번, 할 일을 뽑으려고 (처음부터) 한 번 더 듣는다
  const listen = S.remember((y: Float64Array) => S.transcribe(findSegments(S.frame_energy(y)).map(([a, b]) => y.slice(a, b))));
  const lines = listen(y);
  const decisions = runLlm(S.build_prompts(lines), use);
  const todos = findTodos(listen(y));
  return { lines, decisions, todos };
}

const STAGES = ["구간 찾기", "모델 올리기", "받아쓰기", "LLM 요약", "그 밖"];

function measure(y: Float64Array, cards: string[] = [], refText: string = REF_TEXT) {
  // 켠 카드로 회의록을 한 번 만들고 (가상) 시간 · 비용 · 정확도를 잰다
  if (!refText) throw new Error("정답 글이 비어 있으면 CER을 잴 수 없어요");
  for (const k of Object.keys(TICKS)) delete TICKS[k];
  for (const k of Object.keys(FN)) delete FN[k];
  const use: Use = { calls: 0, in: 0, out: 0 };
  const m = makeMinutes(y, makeStages(cards), use);
  const stages: Record<string, number> = {};
  for (const k of STAGES) stages[k] = TICKS[k] ?? 0;
  const sec = Object.values(stages).reduce((a, b) => a + b, 0) / 1000;
  const server = sec * PRICE.server_sec;
  const tok = (use.in / 1000) * PRICE.in_1k + (use.out / 1000) * PRICE.out_1k;
  return {
    sec, stages, loads: FN["load_asr"]?.[0] ?? 0, calls: use.calls, tok_in: use.in, tok_out: use.out,
    cost_server: server, cost_llm: tok, cost: server + tok, cer: cer(refText, m.lines.join("")),
    n_dec: m.decisions.length, n_todo: m.todos.length, minutes: m, audio_sec: y.length / SR,
  };
}

// ── 같은 일은 한 번만: 소리의 '내용'으로 열쇠를 만들어 같은 소리는 한 번만 계산한다 ──
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)
let runs = 0;

function slowFn(y: Float64Array): number {
  runs += 1; // 느린 함수가 몇 번 실행됐는지 센다
  return y.reduce((a, v) => a + v, 0);
}

const w = remember(slowFn);
const a = Float64Array.from({ length: 8 }, (_, i) => i);
const r1 = w(a);
const r2 = w(Float64Array.from(a)); // 내용이 같은 다른 배열 → 다시 계산하지 않음
const nSame = runs;
const r3 = w(a.map((v) => v + 1)); // 내용이 다른 소리 → 다시 계산
const nOther = runs;
const r4 = w(Float64Array.from(a).reverse()); // 합은 같지만 순서가 다른 소리 → 합으로 열쇠를 만들었다면 여기서 틀린다
const nOrder = runs;
const r5 = w(a.map((v, i) => v + (i === 3 ? 1e-9 : 0))); // 한 표본이 1e-9만 달라도 다른 소리
const nTiny = runs;
const other = remember(slowFn)(a); // remember를 새로 부르면 새 store (요청마다 새 store)
const nNewStore = runs;
console.log(`결과 ${r1}, ${r2}, ${r3}, ${r4} · 느린 함수 실행: 같은 소리 두 번 ${nSame} · +다른 소리 ${nOther} · +순서만 다른 소리 ${nOrder} · +1e-9 다른 소리 ${nTiny} · 새 store ${nNewStore}`);
const okUnit = same([r1, r2, r3, r4], [28, 28, 36, 28]) && same([nSame, nOther, nOrder, nTiny, nNewStore], [1, 2, 3, 4, 5]) && other === 28 && Math.abs(r5 - (28 + 1e-9)) < 1e-12;

// 서비스 전체: 같은 녹음을 두 번 듣는 레거시(결정 사항 · 할 일)에 K4만 끼운다
const base = measure(Y);
const [baseLoads, baseDecodes] = [base.loads, FN["decode"][0]];
const cached = measure(Y, ["K4"]);
console.log(`모델 올린 횟수 ${baseLoads} → ${cached.loads} · decode ${baseDecodes} → ${FN["decode"][0]} · 시간 ×${(base.sec / cached.sec).toFixed(2)} · 결정 ${cached.n_dec} · 할 일 ${cached.n_todo}`);
const okService = cached.loads * 2 === baseLoads && FN["decode"][0] * 2 === baseDecodes && same(cached.minutes, base.minutes) &&
  cached.n_dec === 3 && cached.n_todo === 3 && cached.sec < base.sec * 0.6; // 절반으로 줄고, 회의록은 그대로

check(okUnit && okService, "같은 소리는 한 번만, 합이 같아도 순서가 다르면 다시, 서비스에서는 듣는 횟수가 절반이고 회의록은 그대로여야 해요.");

token.typescript:
// D47 · 토큰이 쌓이는 모양 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d47_token.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델 · LLM은 쓰지 않고 규칙과 가상 시계로 흉내)
//   발언이 늘 때마다 전부 다시 보내면 토큰이 n(n+1)/2로 쌓인다 — 한 번만 보내기
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const SR = 16000;
const FRAME = 320; // 20 ms
const REF: string[] = [ // 회의 발언 14개 (정답 글). 결정 3개 · 할 일 3개가 들어 있음
  "안녕하세요 오늘 회의를 시작하겠습니다",
  "지난주 예약 취소가 열두 건 있었습니다",
  "그래서 예약 확인 문자를 하루 전에 보내기로 결정했습니다",
  "김하나 실장님이 금요일까지 문자 문구를 정리해 주세요",
  "접수 대기 시간이 길다는 의견이 있었습니다",
  "점심시간 접수는 한 명이 맡기로 결정했습니다",
  "박지훈 선생님이 수요일까지 교대표를 만들어 주세요",
  "스케일링 재료 재고는 충분합니다",
  "소독기 점검 일정은 아직 잡히지 않았습니다",
  "토요일 진료는 오후 한 시까지로 결정했습니다",
  "이서연 선생님이 목요일까지 안내문을 인쇄해 주세요",
  "환자 불만은 줄어드는 추세입니다",
  "다른 의견 있으신가요",
  "그럼 오늘 회의는 여기서 마치겠습니다",
];
const REF_TEXT = REF.join(""); // 채점용 정답 글

function makeAudio(): Float64Array {
  // 발언 14개를 사인파 토막으로 만든 녹음. 토막의 소리 크기가 몇 번째 발언인지를 알려 준다. 발언 사이는 0.7초 무음
  const gap = Math.floor((SR * 7) / 10);
  const parts: number[] = new Array(gap).fill(0);
  for (let k = 0; k < REF.length; k++) {
    const frames = 15 + ((k * 5) % 8); // 한 발언은 15 ~ 22조각 (0.3 ~ 0.44초)
    const amp = 0.1 + 0.02 * k;
    for (let n = 0; n < frames * FRAME; n++) parts.push(amp * Math.sin((Math.PI * n) / 16));
    for (let n = 0; n < gap; n++) parts.push(0);
  }
  return Float64Array.from(parts);
}
const Y = makeAudio();

const TICKS: Record<string, number> = {}; // 가상 시계: 단계별로 쌓인 ms (실제 시간이 아니라 작업량이라 컴퓨터가 달라도 같음)
const FN: Record<string, [number, number]> = {}; // 함수별 [부른 횟수, 쌓인 ms]

function tick(stage: string, fn: string, ms: number): void {
  TICKS[stage] = (TICKS[stage] ?? 0) + ms;
  const rec = (FN[fn] ??= [0, 0]);
  rec[0] += 1;
  rec[1] += ms;
}

const RULES =
  "당신은 한빛치과의 회의록 작성을 돕는 매우 유능하고 친절한 인공지능 비서입니다. 아래의 지침을 하나도 빠짐없이 꼼꼼하게 읽고 반드시 지켜 주십시오.\n" +
  "첫째, 회의에서 나온 발언을 처음부터 끝까지 주의 깊게 읽어 주십시오. 둘째, 발언 가운데 무엇인가를 하기로 정한 결정 사항만 골라 주십시오.\n" +
  "셋째, 결정 사항이 아닌 인사말, 질문, 의견, 보고는 절대로 포함하지 마십시오. 넷째, 결정 사항은 발언에 나온 문장을 고치지 말고 그대로 옮겨 주십시오.\n" +
  "다섯째, 결정 사항이 하나도 없으면 없다고만 답해 주십시오. 여섯째, 답은 한국어로, 한 줄에 하나씩 적어 주십시오.\n" +
  "다시 한번 강조합니다. 결정 사항만 골라 주시고, 발언에 없는 내용은 절대로 지어내지 마십시오. 항상 정확하고 간결하게 답해 주시면 감사하겠습니다.\n" +
  "지금까지 요약한 내용이 있더라도 아래 발언을 처음부터 다시 읽고 결정 사항을 다시 정리해 주십시오.";
const SHORT_RULE = "발언에서 결정 사항만 그대로 골라 한 줄에 하나씩 적어 주세요.";
const PRICE = { server_sec: 0.4, in_1k: 4.0, out_1k: 16.0 }; // 가상의 단가(원): 서버 1초 · 입력 1,000토큰 · 출력 1,000토큰

function buildPromptsSlow(lines: string[]): string[] {
  // (레거시) 발언이 하나 늘 때마다 긴 지침과 지금까지의 발언 전부를 다시 보낸다
  const out: string[] = [];
  for (let k = 1; k <= lines.length; k++) out.push(RULES + "\n" + lines.slice(0, k).map((s) => "- " + s).join("\n"));
  return out;
}

function buildPromptsFast(lines: string[]): string[] {
  // (K5) 짧은 지침 한 줄 + 발언 전부, 한 번만. 발언은 줄마다 '- '로 시작해야 LLM이 알아본다
  return [SHORT_RULE + "\n" + lines.map((s) => "- " + s).join("\n")];
}

function countTokens(text: string): number {
  // 토큰 수의 근사: 한글 한 글자 · 영어 낱말 하나 · 숫자 하나 · 기호 하나를 1토큰으로 센다
  return (text.match(/[가-힣]|[A-Za-z]+|\d|[^\s\w]/gu) ?? []).length;
}

function llm(prompt: string): string {
  // LLM 흉내(규칙): '- '로 시작하는 발언 줄 가운데 '결정'이 들어 있는 줄을 그대로 돌려준다. 키도 인터넷도 쓰지 않는다
  tick("LLM 요약", "llm", countTokens(prompt) * 0.001);
  const hits = prompt.split("\n").filter((ln) => ln.startsWith("- ") && ln.replace(/ /g, "").includes("결정")).map((ln) => ln.slice(2).trim());
  return hits.length ? hits.join("\n") : "없음";
}

type Use = { calls: number; in: number; out: number };
function runLlm(prompts: string[], use: Use): string[] {
  // 프롬프트를 차례로 보내고 마지막 답을 돌려준다. 쓴 토큰을 use에 더한다
  let answer = "없음";
  for (const p of prompts) {
    answer = llm(p);
    use.calls += 1;
    use.in += countTokens(p);
    use.out += countTokens(answer);
  }
  return answer === "없음" ? [] : answer.split("\n");
}

type Todo = { who: string; due: string; what: string };
function findTodos(lines: string[]): Todo[] {
  // '○○○ 선생님(실장님)이 ○요일까지 … 주세요' 꼴의 발언에서 담당과 기한을 뽑는다
  tick("그 밖", "find_todos", lines.length * 0.5);
  const todos: Todo[] = [];
  for (const s of lines) {
    const t = s.replace(/ /g, "");
    const m = /([가-힣]{3})(선생님|실장님)이([월화수목금토일]요일)까지/.exec(t);
    if (m && t.includes("주세요")) todos.push({ who: m[1], due: m[3], what: t });
  }
  return todos;
}

// ── 토큰이 쌓이는 모양: 발언이 하나 늘 때마다 전부 다시 보내면 n(n+1)/2줄, 한 번만 보내면 n줄 ──
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

function utteranceLines(prompt: string): number {
  // 프롬프트 안의 발언 줄('- '로 시작) 수
  return prompt.split("\n").filter((ln) => ln.startsWith("- ")).length;
}

function usage(prompts: string[]): [string[], Use] {
  const use: Use = { calls: 0, in: 0, out: 0 };
  const answer = runLlm(prompts, use);
  return [answer, use];
}
const sum = (xs: number[]): number => xs.reduce((a, b) => a + b, 0);
const won = (u: Use): number => (u.in / 1000) * PRICE.in_1k + (u.out / 1000) * PRICE.out_1k;

const n = REF.length;
const slowPrompts = buildPromptsSlow(REF);
const fastPrompts = buildPromptsFast(REF);
const slowLines = sum(slowPrompts.map(utteranceLines));
const fastLines = sum(fastPrompts.map(utteranceLines));
console.log(`발언 ${n}개 → 프롬프트 ${slowPrompts.length}개 · 보낸 발언 줄 ${slowLines} (= n(n+1)/2 = ${(n * (n + 1)) / 2}) → 프롬프트 ${fastPrompts.length}개 · 발언 줄 ${fastLines}`);
console.log("프롬프트마다 발언 줄 수:", JSON.stringify(slowPrompts.map(utteranceLines)));

const want = REF.filter((s) => s.endsWith("결정했습니다")); // 정답: 결정 사항 3개 (정답 글에서 따로 골라 둠)
const [slowAnswer, slowUse] = usage(slowPrompts);
const [fastAnswer, fastUse] = usage(fastPrompts);
const slowTok = slowUse.in + slowUse.out;
const fastTok = fastUse.in + fastUse.out;
const cut = (slowTok - fastTok) / slowTok;
console.log(`LLM 호출 ${slowUse.calls} → ${fastUse.calls} · 토큰 ${slowTok.toLocaleString("en-US")} → ${fastTok.toLocaleString("en-US")} (−${(cut * 100).toFixed(0)}%) · 비용 ${won(slowUse).toFixed(1)}원 → ${won(fastUse).toFixed(1)}원`);

// 함정: 발언을 '- ' 없이 이어 붙이면 LLM이 발언으로 알아보지 못해 답이 비어 버린다 → 토큰이 줄어도 틀린 답은 개선이 아니다
const [badAnswer] = usage([SHORT_RULE + "\n" + REF.join("\n")]);
console.log(`'- ' 없이 보낸 프롬프트의 답: ${JSON.stringify(badAnswer)} (정답은 ${want.length}개)`);

const okShape = slowPrompts.length === n && slowLines === (n * (n + 1)) / 2 && fastPrompts.length === 1 && fastLines === n;
const okAnswer = want.length === 3 && same(slowAnswer, want) && same(fastAnswer, want) && badAnswer.length === 0;
const okTokens = cut >= 0.9 && slowUse.calls === n && fastUse.calls === 1 && countTokens("안녕 ab12!") === 6 && countTokens("😊") === 1 && countTokens("가😊a") === 3;
check(okShape && okAnswer && okTokens, "레거시는 발언 줄이 n(n+1)/2개, 새 방식은 n개. 답은 같고(결정 3개) 토큰은 90% 넘게 줄어야 해요.");

loop.typescript:
// D47 · 멈춘 서버 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d47_loop.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델 · LLM은 쓰지 않고 규칙과 가상 시계로 흉내)
//   일을 요청 자리에서 하면 서버가 멈춘다 — 다른 스레드로 보내고 심장 박동으로 재기
import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";
import { fileURLToPath } from "node:url";
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const SR = 16000;
const FRAME = 320; // 20 ms
const REF: string[] = [ // 회의 발언 14개 (정답 글). 결정 3개 · 할 일 3개가 들어 있음
  "안녕하세요 오늘 회의를 시작하겠습니다",
  "지난주 예약 취소가 열두 건 있었습니다",
  "그래서 예약 확인 문자를 하루 전에 보내기로 결정했습니다",
  "김하나 실장님이 금요일까지 문자 문구를 정리해 주세요",
  "접수 대기 시간이 길다는 의견이 있었습니다",
  "점심시간 접수는 한 명이 맡기로 결정했습니다",
  "박지훈 선생님이 수요일까지 교대표를 만들어 주세요",
  "스케일링 재료 재고는 충분합니다",
  "소독기 점검 일정은 아직 잡히지 않았습니다",
  "토요일 진료는 오후 한 시까지로 결정했습니다",
  "이서연 선생님이 목요일까지 안내문을 인쇄해 주세요",
  "환자 불만은 줄어드는 추세입니다",
  "다른 의견 있으신가요",
  "그럼 오늘 회의는 여기서 마치겠습니다",
];
const REF_TEXT = REF.join(""); // 채점용 정답 글

function makeAudio(): Float64Array {
  // 발언 14개를 사인파 토막으로 만든 녹음. 토막의 소리 크기가 몇 번째 발언인지를 알려 준다. 발언 사이는 0.7초 무음
  const gap = Math.floor((SR * 7) / 10);
  const parts: number[] = new Array(gap).fill(0);
  for (let k = 0; k < REF.length; k++) {
    const frames = 15 + ((k * 5) % 8); // 한 발언은 15 ~ 22조각 (0.3 ~ 0.44초)
    const amp = 0.1 + 0.02 * k;
    for (let n = 0; n < frames * FRAME; n++) parts.push(amp * Math.sin((Math.PI * n) / 16));
    for (let n = 0; n < gap; n++) parts.push(0);
  }
  return Float64Array.from(parts);
}
const Y = makeAudio();

function busyJob(y: Float64Array): number {
  // 몇 초 걸리는 일(받아쓰기) 흉내: 0.3초 동안 잠들어 있다가(받아쓰기 엔진이 계산하는 시간) 소리의 에너지를 정수로 돌려준다
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 300);
  let s = 0;
  for (const v of y) s += v * v;
  return Math.round(s * 1000);
}

type Job = (y: Float64Array) => number;

async function handleSlow(job: Job, y: Float64Array): Promise<number> {
  // (레거시) 요청을 받은 자리에서 일을 끝낸다
  return job(y);
}

const JOBS: Record<string, Job> = { busy: busyJob }; // worker가 이름으로 찾아 쓰는 일 목록 (worker는 이 파일을 다시 불러 같은 목록을 만든다)

function handleFast(job: Job, y: Float64Array): Promise<number> {
  // (K6) 일을 다른 스레드(worker)에 맡기고 결과만 기다린다. 이벤트 루프는 그 사이 다른 요청을 돌본다
  const name = Object.keys(JOBS).find((k) => JOBS[k] === job); // 함수 자체는 worker로 못 보내므로 JOBS에 올린 이름으로 보낸다 (바깥 변수를 써도 됨)
  if (name === undefined) return Promise.reject(new Error("JOBS에 올리지 않은 일은 스레드로 보낼 수 없어요"));
  return new Promise((resolve, reject) => {
    const w = new Worker(fileURLToPath(import.meta.url), { workerData: { name, y } });
    w.once("message", resolve);
    w.once("error", reject);
    w.once("exit", (c) => reject(new Error(`worker가 결과 없이 끝남 (${c})`)));
  });
}

function workerRun(): void {
  // worker 쪽 진입점: 받은 이름의 일을 실행해 결과를 돌려준다
  parentPort!.postMessage(JOBS[workerData.name](workerData.y));
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

async function loopGap(handle: (job: Job, y: Float64Array) => Promise<number>, y: Float64Array): Promise<[number, number, number, number]> {
  // handle(busyJob, y)가 도는 동안 0.02초마다 뛰는 심장 박동이 가장 길게 멈춘 시간 · 뛴 횟수 · 결과 · 일이 끝날 때까지 걸린 시간을 돌려준다
  const gaps: number[] = [];
  let alive = true;
  const beat = (async () => {
    let last = performance.now();
    while (alive) {
      await sleep(20);
      const now = performance.now();
      gaps.push((now - last) / 1000);
      last = now;
    }
  })();
  await sleep(100); // 박동이 자리 잡을 때까지
  gaps.length = 0;
  const t0 = performance.now();
  const result = await handle(busyJob, y);
  const elapsed = (performance.now() - t0) / 1000;
  await sleep(50);
  alive = false;
  await beat;
  return [Math.max(...gaps), gaps.length, result, elapsed];
}

async function steadyGap(handle: (job: Job, y: Float64Array) => Promise<number>, y: Float64Array, tries: number = 3): Promise<number> {
  // 컴퓨터가 잠깐 바빠도 흔들리지 않게, 3번 재서 가장 작은 '가장 길게 멈춘 시간'을 쓴다. (멈춤은 일부러 막는 것이라 더 줄일 수는 없고, 바쁜 컴퓨터는 늘리기만 한다)
  const gaps: number[] = [];
  for (let i = 0; i < tries; i++) gaps.push((await loopGap(handle, y))[0]);
  return Math.min(...gaps);
}

// ── 멈춘 서버: 요청 자리에서 일을 하면 서버가 멈춘다 → 다른 스레드로 보내고 '심장 박동'으로 잰다 ──
// 시간 값(초)이 아니라 비율과 순서로 판정한다: 컴퓨터가 느려져도 '레거시보다 몇 배 덜 멈췄나'는 같다.
const JOB_SEC = 0.3; // busyJob 안의 잠자는 시간(300 ms)과 같아야 함

const OFFSET = 7; // 바깥 변수: worker는 이 파일을 다시 불러 같은 변수를 갖는다
const offsetJob: Job = (y) => busyJob(y) + OFFSET;
JOBS.offset = offsetJob;

function badJob(_y: Float64Array): number {
  throw new Error("boom");
}

JOBS.bad = badJob;

async function errorOf(handle: (job: Job, y: Float64Array) => Promise<number>): Promise<string | null> {
  try {
    await handle(badJob, Y.slice(0, 10));
  } catch (e) {
    return (e as Error).message;
  }
  return null;
}

async function main(): Promise<void> {
  const seg = Y.slice(Math.floor((SR * 7) / 10), Math.floor((SR * 7) / 10) + 4800); // 첫 발언 한 조각 (소리가 있는 조각)
  const want = busyJob(seg); // 정답: 그 자리에서 직접 한 결과 (0이면 소리가 없는 조각이라 시험이 안 됨)
  const [gapS, beatsS, resS, tookS] = await loopGap(handleSlow, seg);
  const [gapF, beatsF, resF, tookF] = await loopGap(handleFast, seg);
  console.log(`레거시: 가장 길게 멈춘 시간 ${gapS.toFixed(2)}초 · 박동 ${beatsS}번 · 일 ${tookS.toFixed(2)}초`);
  console.log(`K6    : 가장 길게 멈춘 시간 ${gapF.toFixed(2)}초 · 박동 ${beatsF}번 · 일 ${tookF.toFixed(2)}초`);
  const okResult = want > 0 && resS === want && resF === want; // 어느 쪽이든 결과는 job(y)와 같다
  const okGap = gapS >= JOB_SEC * 0.9 && gapF < gapS * 0.5 && beatsF > beatsS; // 레거시는 일하는 내내 멈추고, K6는 그 절반도 안 멈춘다
  const okSameWork = tookS >= JOB_SEC * 0.9 && tookF >= JOB_SEC * 0.9; // 일 자체는 줄지 않는다(응답성만 좋아짐)
  const okError = (await errorOf(handleSlow)) === "boom" && (await errorOf(handleFast)) === "boom"; // 일이 실패하면 둘 다 호출한 쪽에 오류를 알린다
  const gapSteady = await steadyGap(handleFast, seg); // 3번 재서 가장 작은 값 (컴퓨터가 잠깐 바빠도 흔들리지 않게)
  const okAbs = gapS > 0.1 && 0.1 >= gapSteady; // 원본 목표 ④: 0.1초 넘게 멈추지 않을 것
  const okOuter = (await handleFast(offsetJob, seg)) === want + OFFSET; // 바깥 변수를 쓰는 일도 결과가 같다
  check(okResult && okGap && okAbs && okOuter && okSameWork && okError, "결과는 job(y)와 같고, 스레드로 보내면 멈춤이 레거시의 절반 아래이며 일 자체의 시간은 줄지 않고, 오류는 전달되어야 해요.");
}

if (isMainThread) main();
else workerRun();

