// D47 · 카드로 목표 맞추기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d47_report.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델 · LLM은 쓰지 않고 규칙과 가상 시계로 흉내)
//   카드를 켜고 끄며 목표 5개를 채점하고 전후 비교 보고서(JSON)를 만든다
import { readFileSync, writeFileSync } from "node:fs";
