# D47 · 정리 퀴즈 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d47_recap.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델 · LLM은 쓰지 않고 규칙과 가상 시계로 흉내)
#   오늘 배운 숫자 8문항, 정답은 모두 코드를 돌려 얻은 값과 비교
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


import hashlib, math, re
from array import array


SR = 16000
FRAME = 320                                              # 20 ms
REF = [                                                  # 회의 발언 14개 (정답 글). 결정 3개 · 할 일 3개가 들어 있음
    "안녕하세요 오늘 회의를 시작하겠습니다",
    "지난주 예약 취소가 열두 건 있었습니다",
    "그래서 예약 확인 문자를 하루 전에 보내기로 결정했습니다",
    "김하나 실장님이 금요일까지 문자 문구를 정리해 주세요",
    "접수 대기 시간이 길다는 의견이 있었습니다",
    "점심시간 접수는 한 명이 맡기로 결정했습니다",
    "박지훈 선생님이 수요일까지 교대표를 만들어 주세요",
    "스케일링 재료 재고는 충분합니다",
    "소독기 점검 일정은 아직 잡히지 않았습니다",
    "토요일 진료는 오후 한 시까지로 결정했습니다",
    "이서연 선생님이 목요일까지 안내문을 인쇄해 주세요",
    "환자 불만은 줄어드는 추세입니다",
    "다른 의견 있으신가요",
    "그럼 오늘 회의는 여기서 마치겠습니다",
]
REF_TEXT = "".join(REF)                                  # 채점용 정답 글


def make_audio():
    """발언 14개를 사인파 토막으로 만든 녹음. 토막의 소리 크기가 몇 번째 발언인지를 알려 준다. 발언 사이는 0.7초 무음."""
    y = array("d", [0.0] * (SR * 7 // 10))
    for k in range(len(REF)):
        frames = 15 + (k * 5) % 8                        # 한 발언은 15 ~ 22조각 (0.3 ~ 0.44초)
        amp = 0.10 + 0.02 * k
        y.extend(amp * math.sin(math.pi * n / 16) for n in range(frames * FRAME))
        y.extend([0.0] * (SR * 7 // 10))
    return y


Y = make_audio()


TICKS = {}                                               # 가상 시계: 단계별로 쌓인 ms (실제 시간이 아니라 작업량이라 컴퓨터가 달라도 같음)
FN = {}                                                  # 함수별 [부른 횟수, 쌓인 ms]


def tick(stage, fn, ms):
    TICKS[stage] = TICKS.get(stage, 0.0) + ms
    rec = FN.setdefault(fn, [0, 0.0])
    rec[0] += 1
    rec[1] += ms


def frame_energy_slow(y):
    """(레거시) 20 ms 조각마다 소리의 크기(RMS)를 잰다. 표본을 하나씩 더한다."""
    out = []
    for i in range(len(y) // FRAME):
        total = 0.0
        for j in range(FRAME):
            total += float(y[i * FRAME + j]) ** 2
        out.append(math.sqrt(total / FRAME))
    tick("구간 찾기", "frame_energy", len(y) * 0.001)
    return out


def frame_energy_fast(y):
    """(K1) 조각 단위로 한꺼번에 계산. numpy가 없으니 속도 차이는 가상 시계(50배 빠름)로 흉내 낸다."""
    n = len(y) // FRAME
    out = [math.sqrt(math.fsum(v * v for v in y[i * FRAME:(i + 1) * FRAME]) / FRAME) for i in range(n)]
    tick("구간 찾기", "frame_energy", len(y) * 0.00002)
    return out


def find_segments(energy, thr=0.02, min_sil=25, pad=5):
    """크기가 thr를 넘는 조각을 잇고, 0.5초(25조각) 넘게 조용하면 발언을 끊는다. → [(시작 표본, 끝 표본)]"""
    spans, start, quiet = [], None, 0
    for i, e in enumerate(list(energy) + [0.0] * (min_sil + 1)):
        if e > thr:
            if start is None:
                start = i
            quiet = 0
        elif start is not None:
            quiet += 1
            if quiet > min_sil:
                spans.append((max(0, start - pad) * FRAME, (i - quiet + 1 + pad) * FRAME))
                start, quiet = None, 0
    return spans


LOAD_MS = {"fp32": 1700.0, "int8": 1100.0}               # 모델 올리는 비용 (가상 ms)
PER_SAMPLE_MS = {"fp32": 0.025, "int8": 0.012}           # 소리 표본 하나를 받아쓰는 비용: int8이 더 싸다
CALL_MS = 100.0                                          # decode를 한 번 부르는 고정 비용
BATCH_FACTOR = 0.6                                       # 여러 조각을 한꺼번에 계산하면 조각당 비용이 줄어든다
INT8_SLIP = {9: ("습니다", "슴니다")}                       # 작은 모델(int8)이 한 글자를 잘못 들음 (정확도와 속도의 맞바꿈)


class Asr:
    """받아쓰기 모델 흉내. 토막의 소리 크기로 몇 번째 발언인지 알아내 그 글을 돌려준다."""

    def __init__(self, kind):
        self.kind = kind

    def decode(self, segs):
        """조각 여러 개 → 글 여러 개 (한 번 부르기)."""
        pad = SR // 2 + int(SR * 0.8)                    # 앞 0.5초 · 뒤 0.8초 무음을 붙여 넣음
        factor = 1.0 if len(segs) == 1 else BATCH_FACTOR
        ms = CALL_MS + sum((len(s) + pad) * PER_SAMPLE_MS[self.kind] * factor for s in segs)
        tick("받아쓰기", "decode", ms)
        out = []
        for s in segs:
            k = round((max(abs(v) for v in s) - 0.10) / 0.02) if len(s) else -1
            text = REF[k] if 0 <= k < len(REF) else ""
            if self.kind == "int8" and k in INT8_SLIP:
                text = text.replace(*INT8_SLIP[k], 1)
            out.append(text)
        return out


def load_asr(kind="fp32"):
    """받아쓰기 모델을 메모리에 올린다. 올릴 때마다 비용이 든다."""
    if kind not in LOAD_MS:
        raise ValueError(f"kind는 fp32 또는 int8: {kind}")
    tick("모델 올리기", "load_asr", LOAD_MS[kind])
    return Asr(kind)


def decode_one(asr, y):
    return asr.decode([y])[0]


def cached_loader():
    """(K2) 같은 kind는 한 번만 올린다. kind마다 따로 넣어 둔다."""
    cache = {}

    def get_asr(kind="fp32"):
        if kind not in cache:
            cache[kind] = load_asr(kind)
        return cache[kind]

    return get_asr


def transcribe_slow(segs, get_asr=load_asr):
    """(레거시) 조각마다 모델을 준비하고 한 조각씩 받아쓴다."""
    return [decode_one(get_asr("fp32"), seg) for seg in segs]


def transcribe_fast(segs, get_asr):
    """(K3) 작은 모델(int8)로 모든 조각을 한꺼번에."""
    return get_asr("int8").decode(list(segs))


RULES = ("당신은 한빛치과의 회의록 작성을 돕는 매우 유능하고 친절한 인공지능 비서입니다. 아래의 지침을 하나도 빠짐없이 꼼꼼하게 읽고 반드시 지켜 주십시오.\n"
         "첫째, 회의에서 나온 발언을 처음부터 끝까지 주의 깊게 읽어 주십시오. 둘째, 발언 가운데 무엇인가를 하기로 정한 결정 사항만 골라 주십시오.\n"
         "셋째, 결정 사항이 아닌 인사말, 질문, 의견, 보고는 절대로 포함하지 마십시오. 넷째, 결정 사항은 발언에 나온 문장을 고치지 말고 그대로 옮겨 주십시오.\n"
         "다섯째, 결정 사항이 하나도 없으면 없다고만 답해 주십시오. 여섯째, 답은 한국어로, 한 줄에 하나씩 적어 주십시오.\n"
         "다시 한번 강조합니다. 결정 사항만 골라 주시고, 발언에 없는 내용은 절대로 지어내지 마십시오. 항상 정확하고 간결하게 답해 주시면 감사하겠습니다.\n"
         "지금까지 요약한 내용이 있더라도 아래 발언을 처음부터 다시 읽고 결정 사항을 다시 정리해 주십시오.")
SHORT_RULE = "발언에서 결정 사항만 그대로 골라 한 줄에 하나씩 적어 주세요."
PRICE = {"server_sec": 0.4, "in_1k": 4.0, "out_1k": 16.0}   # 가상의 단가(원): 서버 1초 · 입력 1,000토큰 · 출력 1,000토큰


def build_prompts_slow(lines):
    """(레거시) 발언이 하나 늘 때마다 긴 지침과 지금까지의 발언 전부를 다시 보낸다."""
    return [RULES + "\n" + "\n".join("- " + s for s in lines[:k]) for k in range(1, len(lines) + 1)]


def build_prompts_fast(lines):
    """(K5) 짧은 지침 한 줄 + 발언 전부, 한 번만. 발언은 줄마다 '- '로 시작해야 LLM이 알아본다."""
    return [SHORT_RULE + "\n" + "\n".join("- " + s for s in lines)]


def count_tokens(text):
    """토큰 수의 근사: 한글 한 글자 · 영어 낱말 하나 · 숫자 하나 · 기호 하나를 1토큰으로 센다."""
    return len(re.findall(r"[가-힣]|[A-Za-z]+|\d|[^\s\w]", text))


def llm(prompt):
    """LLM 흉내(규칙): '- '로 시작하는 발언 줄 가운데 '결정'이 들어 있는 줄을 그대로 돌려준다. 키도 인터넷도 쓰지 않는다."""
    tick("LLM 요약", "llm", count_tokens(prompt) * 0.001)
    hits = [ln[2:].strip() for ln in prompt.split("\n") if ln.startswith("- ") and "결정" in ln.replace(" ", "")]
    return "\n".join(hits) if hits else "없음"


def run_llm(prompts, use):
    """프롬프트를 차례로 보내고 마지막 답을 돌려준다. 쓴 토큰을 use에 더한다."""
    answer = "없음"
    for p in prompts:
        answer = llm(p)
        use["calls"] += 1
        use["in"] += count_tokens(p)
        use["out"] += count_tokens(answer)
    return [] if answer == "없음" else answer.split("\n")


def find_todos(lines):
    """'○○○ 선생님(실장님)이 ○요일까지 … 주세요' 꼴의 발언에서 담당과 기한을 뽑는다."""
    tick("그 밖", "find_todos", len(lines) * 0.5)
    todos = []
    for s in lines:
        t = s.replace(" ", "")
        m = re.search(r"([가-힣]{3})(선생님|실장님)이([월화수목금토일]요일)까지", t)
        if m and "주세요" in t:
            todos.append({"who": m.group(1), "due": m.group(3), "what": t})
    return todos


def cer(ref, hyp):
    """글자 오류율: 편집 거리 / 정답 글자 수 (공백 · 기호는 뺀다)."""
    r, h = [re.sub(r"[^0-9A-Za-z가-힣]", "", s) for s in (ref, hyp)]
    d = list(range(len(h) + 1))
    for i, a in enumerate(r, 1):
        prev, d[0] = d[0], i
        for j, b in enumerate(h, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (a != b))
    return d[-1] / max(1, len(r))


def identity(fn):
    """(레거시) 아무것도 기억하지 않는다."""
    return fn


def remember(fn):
    """(K4) 소리의 '내용'으로 열쇠를 만들어, 같은 소리는 한 번만 계산한다."""
    store = {}

    def wrapper(y):
        key = hashlib.sha1(array("d", y).tobytes()).hexdigest()
        if key not in store:
            store[key] = fn(y)
        return store[key]

    return wrapper


def make_stages(cards=()):
    """카드(K1~K5)를 켠 만큼만 새 함수를 끼우고, 나머지 자리는 레거시 함수가 맡는다."""
    ga = cached_loader() if "K2" in cards else load_asr
    trans = transcribe_fast if "K3" in cards else transcribe_slow
    return {"frame_energy": frame_energy_fast if "K1" in cards else frame_energy_slow,
            "transcribe": lambda segs: trans(segs, ga),
            "remember": remember if "K4" in cards else identity,
            "build_prompts": build_prompts_fast if "K5" in cards else build_prompts_slow}


def make_minutes(y, S, use):
    """녹음 → 회의록. 결정 사항을 뽑으려고 한 번, 할 일을 뽑으려고 (처음부터) 한 번 더 듣는다."""
    def listen(y):
        spans = find_segments(S["frame_energy"](y))
        return S["transcribe"]([y[a:b] for a, b in spans])

    listen = S["remember"](listen)
    lines = listen(y)
    decisions = run_llm(S["build_prompts"](lines), use)
    todos = find_todos(listen(y))
    return {"lines": lines, "decisions": decisions, "todos": todos}


STAGES = ("구간 찾기", "모델 올리기", "받아쓰기", "LLM 요약", "그 밖")


def measure(y, cards=(), ref_text=REF_TEXT):
    """켠 카드로 회의록을 한 번 만들고 (가상) 시간 · 비용 · 정확도를 잰다."""
    if not ref_text:
        raise ValueError("정답 글이 비어 있으면 CER을 잴 수 없어요")
    TICKS.clear()
    FN.clear()
    use = {"calls": 0, "in": 0, "out": 0}
    m = make_minutes(y, make_stages(cards), use)
    stages = {k: TICKS.get(k, 0.0) for k in STAGES}
    sec = sum(stages.values()) / 1000
    server = sec * PRICE["server_sec"]
    tok = use["in"] / 1000 * PRICE["in_1k"] + use["out"] / 1000 * PRICE["out_1k"]
    return {"sec": sec, "stages": stages, "loads": FN.get("load_asr", [0])[0], "calls": use["calls"], "tok_in": use["in"], "tok_out": use["out"],
            "cost_server": server, "cost_llm": tok, "cost": server + tok, "cer": cer(ref_text, "".join(m["lines"])),
            "n_dec": len(m["decisions"]), "n_todo": len(m["todos"]), "minutes": m, "audio_sec": len(y) / SR}


# ── 정리 퀴즈: 오늘 배운 숫자 8문항, 정답은 모두 코드를 돌려 얻은 값과 비교 ──
def amdahl(p, s):
    """p: 그 단계의 비중(0 ~ 1), s: 그 단계가 빨라진 배수 → 전체가 빨라지는 배수"""
    return 1 / ((1 - p) + p / s)


def saved(before, after):
    """(줄어든 비율 %, 빨라진 배수) — 둘 다 소수 첫째 자리"""
    if before <= 0 or after <= 0:
        raise ValueError("before와 after는 0보다 커야 해요")
    return round_half_up((before - after) / before * 100, 1), round_half_up(before / after, 1)


BASE = measure(Y)                                        # 레거시 그대로 한 번 실행


def slowest_stage():
    return max(BASE["stages"], key=BASE["stages"].get)


def k1_only_speedup():
    return round_half_up(BASE["sec"] / measure(Y, ("K1",))["sec"], 1)


def legacy_utterance_lines():
    return sum(1 for p in build_prompts_slow(REF) for ln in p.split("\n") if ln.startswith("- "))


def remember_runs():
    runs = []
    w = remember(lambda y: runs.append(1) or len(y))
    w(array("d", [1.0, 2.0, 3.0]))
    w(array("d", [1.0, 2.0, 3.0]))                       # 내용이 같은 소리
    return len(runs)


def int8_cer_change():
    old, new = BASE["cer"], measure(Y, ("K3",))["cer"]   # 같은 서비스에서 fp32 → int8(K3)만 바뀜
    if new < old:
        return "줄었다"
    if new == old:
        return "같다"
    return "조금 올랐다" if new - old <= 0.02 else "많이 올랐다"


QUIZ = [
    ("Q1. 레거시에서 가장 오래 걸린 단계는?", "모델 올리기", slowest_stage),
    ("Q2. 레거시는 받아쓰기 모델을 몇 번 올리나?", 28, lambda: BASE["loads"]),
    ("Q3. 비중 50%인 단계를 2배 빠르게 하면 전체는 몇 배? (소수 둘째 자리)", 1.33, lambda: round_half_up(amdahl(0.5, 2), 2)),
    ("Q4. 이중 반복문(구간 찾기)만 고치면 전체는 몇 배 빨라지나? (소수 첫째 자리)", 1.0, k1_only_speedup),
    ("Q5. 레거시는 발언 14개를 LLM에 보낼 때 발언 줄을 모두 몇 줄 보내나?", 105, legacy_utterance_lines),
    ("Q6. 내용이 같은 소리를 두 번 주면, remember로 감싼 느린 함수는 몇 번 실행되나?", 1, remember_runs),
    ("Q7. 60초가 15초가 되면 (줄어든 비율 %, 빨라진 배수)는?", (75.0, 4.0), lambda: saved(60, 15)),
    ("Q8. 작은 모델(int8)로 바꾼 뒤 글자 오류율은? (줄었다 / 같다 / 조금 올랐다)", "조금 올랐다", int8_cer_change),
]
score = 0
for q, want, compute in QUIZ:
    got = compute()
    score += got == want
    print(f"{'O' if got == want else 'X'} {q}  → {got}")
print(f"정리 퀴즈 {score} / {len(QUIZ)}")
check(len(QUIZ) == 8 and score == 8, "퀴즈 8문항의 정답이 코드를 돌려 얻은 값과 모두 같아야 해요.")

recap.typescript:
// D47 · 정리 퀴즈 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d47_recap.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델 · LLM은 쓰지 않고 규칙과 가상 시계로 흉내)
//   오늘 배운 숫자 8문항, 정답은 모두 코드를 돌려 얻은 값과 비교
import { createHash } from "node:crypto";
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const SR = 16000;
const FRAME = 320; // 20 ms
const REF: string[] = [ // 회의 발언 14개 (정답 글). 결정 3개 · 할 일 3개가 들어 있음
  "안녕하세요 오늘 회의를 시작하겠습니다",
  "지난주 예약 취소가 열두 건 있었습니다",
  "그래서 예약 확인 문자를 하루 전에 보내기로 결정했습니다",
  "김하나 실장님이 금요일까지 문자 문구를 정리해 주세요",
  "접수 대기 시간이 길다는 의견이 있었습니다",
  "점심시간 접수는 한 명이 맡기로 결정했습니다",
  "박지훈 선생님이 수요일까지 교대표를 만들어 주세요",
  "스케일링 재료 재고는 충분합니다",
  "소독기 점검 일정은 아직 잡히지 않았습니다",
  "토요일 진료는 오후 한 시까지로 결정했습니다",
  "이서연 선생님이 목요일까지 안내문을 인쇄해 주세요",
  "환자 불만은 줄어드는 추세입니다",
  "다른 의견 있으신가요",
  "그럼 오늘 회의는 여기서 마치겠습니다",
];
const REF_TEXT = REF.join(""); // 채점용 정답 글

function makeAudio(): Float64Array {
  // 발언 14개를 사인파 토막으로 만든 녹음. 토막의 소리 크기가 몇 번째 발언인지를 알려 준다. 발언 사이는 0.7초 무음
  const gap = Math.floor((SR * 7) / 10);
  const parts: number[] = new Array(gap).fill(0);
  for (let k = 0; k < REF.length; k++) {
    const frames = 15 + ((k * 5) % 8); // 한 발언은 15 ~ 22조각 (0.3 ~ 0.44초)
    const amp = 0.1 + 0.02 * k;
    for (let n = 0; n < frames * FRAME; n++) parts.push(amp * Math.sin((Math.PI * n) / 16));
    for (let n = 0; n < gap; n++) parts.push(0);
  }
  return Float64Array.from(parts);
}
const Y = makeAudio();

const TICKS: Record<string, number> = {}; // 가상 시계: 단계별로 쌓인 ms (실제 시간이 아니라 작업량이라 컴퓨터가 달라도 같음)
const FN: Record<string, [number, number]> = {}; // 함수별 [부른 횟수, 쌓인 ms]

function tick(stage: string, fn: string, ms: number): void {
  TICKS[stage] = (TICKS[stage] ?? 0) + ms;
  const rec = (FN[fn] ??= [0, 0]);
  rec[0] += 1;
  rec[1] += ms;
}

function frameEnergySlow(y: Float64Array): number[] {
  // (레거시) 20 ms 조각마다 소리의 크기(RMS)를 잰다. 표본을 하나씩 더한다
  const out: number[] = [];
  for (let i = 0; i < Math.floor(y.length / FRAME); i++) {
    let total = 0;
    for (let j = 0; j < FRAME; j++) total += y[i * FRAME + j] ** 2;
    out.push(Math.sqrt(total / FRAME));
  }
  tick("구간 찾기", "frame_energy", y.length * 0.001);
  return out;
}

function frameEnergyFast(y: Float64Array): number[] {
  // (K1) 조각 단위로 한꺼번에 계산. 속도 차이는 가상 시계(50배 빠름)로 흉내 낸다
  const n = Math.floor(y.length / FRAME);
  const out: number[] = [];
  for (let i = 0; i < n; i++) out.push(Math.sqrt(y.slice(i * FRAME, (i + 1) * FRAME).reduce((a, v) => a + v * v, 0) / FRAME));
  tick("구간 찾기", "frame_energy", y.length * 0.00002);
  return out;
}

function findSegments(energy: number[], thr = 0.02, minSil = 25, pad = 5): [number, number][] {
  // 크기가 thr를 넘는 조각을 잇고, 0.5초(25조각) 넘게 조용하면 발언을 끊는다. → [(시작 표본, 끝 표본)]
  const spans: [number, number][] = [];
  let start: number | null = null;
  let quiet = 0;
  const e2 = [...energy, ...new Array(minSil + 1).fill(0)];
  for (let i = 0; i < e2.length; i++) {
    if (e2[i] > thr) {
      if (start === null) start = i;
      quiet = 0;
    } else if (start !== null) {
      quiet += 1;
      if (quiet > minSil) {
        spans.push([Math.max(0, start - pad) * FRAME, (i - quiet + 1 + pad) * FRAME]);
        start = null;
        quiet = 0;
      }
    }
  }
  return spans;
}

const LOAD_MS: Record<string, number> = { fp32: 1700, int8: 1100 }; // 모델 올리는 비용 (가상 ms)
const PER_SAMPLE_MS: Record<string, number> = { fp32: 0.025, int8: 0.012 }; // 소리 표본 하나를 받아쓰는 비용: int8이 더 싸다
const CALL_MS = 100; // decode를 한 번 부르는 고정 비용
const BATCH_FACTOR = 0.6; // 여러 조각을 한꺼번에 계산하면 조각당 비용이 줄어든다
const INT8_SLIP: Record<number, [string, string]> = { 9: ["습니다", "슴니다"] }; // 작은 모델(int8)이 한 글자를 잘못 들음 (정확도와 속도의 맞바꿈)

class Asr {
  // 받아쓰기 모델 흉내. 토막의 소리 크기로 몇 번째 발언인지 알아내 그 글을 돌려준다
  kind: string;
  constructor(kind: string) {
    this.kind = kind;
  }
  decode(segs: Float64Array[]): string[] {
    // 조각 여러 개 → 글 여러 개 (한 번 부르기)
    const pad = Math.floor(SR / 2) + Math.floor(SR * 0.8); // 앞 0.5초 · 뒤 0.8초 무음을 붙여 넣음
    const factor = segs.length === 1 ? 1.0 : BATCH_FACTOR;
    let ms = CALL_MS;
    for (const s of segs) ms += (s.length + pad) * PER_SAMPLE_MS[this.kind] * factor;
    tick("받아쓰기", "decode", ms);
    return segs.map((s) => {
      let peak = 0;
      for (const v of s) peak = Math.max(peak, Math.abs(v));
      const k = s.length ? Math.round((peak - 0.1) / 0.02) : -1;
      let text = k >= 0 && k < REF.length ? REF[k] : "";
      if (this.kind === "int8" && Object.hasOwn(INT8_SLIP, k)) text = text.replace(INT8_SLIP[k][0], INT8_SLIP[k][1]);
      return text;
    });
  }
}

function loadAsr(kind: string = "fp32"): Asr {
  // 받아쓰기 모델을 메모리에 올린다. 올릴 때마다 비용이 든다
  if (!Object.hasOwn(LOAD_MS, kind)) throw new Error(`kind는 fp32 또는 int8: ${kind}`);
  tick("모델 올리기", "load_asr", LOAD_MS[kind]);
  return new Asr(kind);
}

const decodeOne = (asr: Asr, y: Float64Array): string => asr.decode([y])[0];

function cachedLoader(): (kind?: string) => Asr {
  // (K2) 같은 kind는 한 번만 올린다. kind마다 따로 넣어 둔다
  const cache = new Map<string, Asr>();
  return (kind: string = "fp32") => {
    if (!cache.has(kind)) cache.set(kind, loadAsr(kind));
    return cache.get(kind) as Asr;
  };
}

function transcribeSlow(segs: Float64Array[], getAsr: (kind?: string) => Asr = loadAsr): string[] {
  // (레거시) 조각마다 모델을 준비하고 한 조각씩 받아쓴다
  return segs.map((seg) => decodeOne(getAsr("fp32"), seg));
}

function transcribeFast(segs: Float64Array[], getAsr: (kind?: string) => Asr): string[] {
  // (K3) 작은 모델(int8)로 모든 조각을 한꺼번에
  return getAsr("int8").decode([...segs]);
}

const RULES =
  "당신은 한빛치과의 회의록 작성을 돕는 매우 유능하고 친절한 인공지능 비서입니다. 아래의 지침을 하나도 빠짐없이 꼼꼼하게 읽고 반드시 지켜 주십시오.\n" +
  "첫째, 회의에서 나온 발언을 처음부터 끝까지 주의 깊게 읽어 주십시오. 둘째, 발언 가운데 무엇인가를 하기로 정한 결정 사항만 골라 주십시오.\n" +
  "셋째, 결정 사항이 아닌 인사말, 질문, 의견, 보고는 절대로 포함하지 마십시오. 넷째, 결정 사항은 발언에 나온 문장을 고치지 말고 그대로 옮겨 주십시오.\n" +
  "다섯째, 결정 사항이 하나도 없으면 없다고만 답해 주십시오. 여섯째, 답은 한국어로, 한 줄에 하나씩 적어 주십시오.\n" +
  "다시 한번 강조합니다. 결정 사항만 골라 주시고, 발언에 없는 내용은 절대로 지어내지 마십시오. 항상 정확하고 간결하게 답해 주시면 감사하겠습니다.\n" +
  "지금까지 요약한 내용이 있더라도 아래 발언을 처음부터 다시 읽고 결정 사항을 다시 정리해 주십시오.";
const SHORT_RULE = "발언에서 결정 사항만 그대로 골라 한 줄에 하나씩 적어 주세요.";
const PRICE = { server_sec: 0.4, in_1k: 4.0, out_1k: 16.0 }; // 가상의 단가(원): 서버 1초 · 입력 1,000토큰 · 출력 1,000토큰

function buildPromptsSlow(lines: string[]): string[] {
  // (레거시) 발언이 하나 늘 때마다 긴 지침과 지금까지의 발언 전부를 다시 보낸다
  const out: string[] = [];
  for (let k = 1; k <= lines.length; k++) out.push(RULES + "\n" + lines.slice(0, k).map((s) => "- " + s).join("\n"));
  return out;
}

function buildPromptsFast(lines: string[]): string[] {
  // (K5) 짧은 지침 한 줄 + 발언 전부, 한 번만. 발언은 줄마다 '- '로 시작해야 LLM이 알아본다
  return [SHORT_RULE + "\n" + lines.map((s) => "- " + s).join("\n")];
}

function countTokens(text: string): number {
  // 토큰 수의 근사: 한글 한 글자 · 영어 낱말 하나 · 숫자 하나 · 기호 하나를 1토큰으로 센다
  return (text.match(/[가-힣]|[A-Za-z]+|\d|[^\s\w]/gu) ?? []).length;
}

function llm(prompt: string): string {
  // LLM 흉내(규칙): '- '로 시작하는 발언 줄 가운데 '결정'이 들어 있는 줄을 그대로 돌려준다. 키도 인터넷도 쓰지 않는다
  tick("LLM 요약", "llm", countTokens(prompt) * 0.001);
  const hits = prompt.split("\n").filter((ln) => ln.startsWith("- ") && ln.replace(/ /g, "").includes("결정")).map((ln) => ln.slice(2).trim());
  return hits.length ? hits.join("\n") : "없음";
}

type Use = { calls: number; in: number; out: number };
function runLlm(prompts: string[], use: Use): string[] {
  // 프롬프트를 차례로 보내고 마지막 답을 돌려준다. 쓴 토큰을 use에 더한다
  let answer = "없음";
  for (const p of prompts) {
    answer = llm(p);
    use.calls += 1;
    use.in += countTokens(p);
    use.out += countTokens(answer);
  }
  return answer === "없음" ? [] : answer.split("\n");
}

type Todo = { who: string; due: string; what: string };
function findTodos(lines: string[]): Todo[] {
  // '○○○ 선생님(실장님)이 ○요일까지 … 주세요' 꼴의 발언에서 담당과 기한을 뽑는다
  tick("그 밖", "find_todos", lines.length * 0.5);
  const todos: Todo[] = [];
  for (const s of lines) {
    const t = s.replace(/ /g, "");
    const m = /([가-힣]{3})(선생님|실장님)이([월화수목금토일]요일)까지/.exec(t);
    if (m && t.includes("주세요")) todos.push({ who: m[1], due: m[3], what: t });
  }
  return todos;
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 편집 거리 / 정답 글자 수 (공백 · 기호는 뺀다)
  const r = ref.replace(/[^0-9A-Za-z가-힣]/g, "");
  const h = hyp.replace(/[^0-9A-Za-z가-힣]/g, "");
  const d = Array.from({ length: h.length + 1 }, (_, i) => i);
  for (let i = 1; i <= r.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= h.length; j++) {
      const cur = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (r[i - 1] !== h[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return d[h.length] / Math.max(1, r.length);
}

function identity<A, B>(fn: (a: A) => B): (a: A) => B {
  // (레거시) 아무것도 기억하지 않는다
  return fn;
}

function remember<B>(fn: (y: Float64Array) => B): (y: Float64Array) => B {
  // (K4) 소리의 '내용'으로 열쇠를 만들어, 같은 소리는 한 번만 계산한다
  const store = new Map<string, B>();
  return (y) => {
    const key = createHash("sha1").update(Buffer.from(Float64Array.from(y).buffer)).digest("hex");
    if (!store.has(key)) store.set(key, fn(y));
    return store.get(key) as B;
  };
}

type Stages = {
  frame_energy: (y: Float64Array) => number[];
  transcribe: (segs: Float64Array[]) => string[];
  remember: (fn: (y: Float64Array) => string[]) => (y: Float64Array) => string[];
  build_prompts: (lines: string[]) => string[];
};

function makeStages(cards: string[] = []): Stages {
  // 카드(K1~K5)를 켠 만큼만 새 함수를 끼우고, 나머지 자리는 레거시 함수가 맡는다
  const ga = cards.includes("K2") ? cachedLoader() : loadAsr;
  const trans = cards.includes("K3") ? transcribeFast : transcribeSlow;
  return {
    frame_energy: cards.includes("K1") ? frameEnergyFast : frameEnergySlow,
    transcribe: (segs) => trans(segs, ga),
    remember: cards.includes("K4") ? remember : identity,
    build_prompts: cards.includes("K5") ? buildPromptsFast : buildPromptsSlow,
  };
}

function makeMinutes(y: Float64Array, S: Stages, use: Use) {
  // 녹음 → 회의록. 결정 사항을 뽑으려고 한 번, 할 일을 뽑으려고 (처음부터) 한 번 더 듣는다
  const listen = S.remember((y: Float64Array) => S.transcribe(findSegments(S.frame_energy(y)).map(([a, b]) => y.slice(a, b))));
  const lines = listen(y);
  const decisions = runLlm(S.build_prompts(lines), use);
  const todos = findTodos(listen(y));
  return { lines, decisions, todos };
}

const STAGES = ["구간 찾기", "모델 올리기", "받아쓰기", "LLM 요약", "그 밖"];

function measure(y: Float64Array, cards: string[] = [], refText: string = REF_TEXT) {
  // 켠 카드로 회의록을 한 번 만들고 (가상) 시간 · 비용 · 정확도를 잰다
  if (!refText) throw new Error("정답 글이 비어 있으면 CER을 잴 수 없어요");
  for (const k of Object.keys(TICKS)) delete TICKS[k];
  for (const k of Object.keys(FN)) delete FN[k];
  const use: Use = { calls: 0, in: 0, out: 0 };
  const m = makeMinutes(y, makeStages(cards), use);
  const stages: Record<string, number> = {};
  for (const k of STAGES) stages[k] = TICKS[k] ?? 0;
  const sec = Object.values(stages).reduce((a, b) => a + b, 0) / 1000;
  const server = sec * PRICE.server_sec;
  const tok = (use.in / 1000) * PRICE.in_1k + (use.out / 1000) * PRICE.out_1k;
  return {
    sec, stages, loads: FN["load_asr"]?.[0] ?? 0, calls: use.calls, tok_in: use.in, tok_out: use.out,
    cost_server: server, cost_llm: tok, cost: server + tok, cer: cer(refText, m.lines.join("")),
    n_dec: m.decisions.length, n_todo: m.todos.length, minutes: m, audio_sec: y.length / SR,
  };
}

// ── 정리 퀴즈: 오늘 배운 숫자 8문항, 정답은 모두 코드를 돌려 얻은 값과 비교 ──
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

function amdahl(p: number, s: number): number {
  // p: 그 단계의 비중(0 ~ 1), s: 그 단계가 빨라진 배수 → 전체가 빨라지는 배수
  return 1 / (1 - p + p / s);
}

function saved(before: number, after: number): [number, number] {
  // (줄어든 비율 %, 빨라진 배수) — 둘 다 소수 첫째 자리
  if (before <= 0 || after <= 0) throw new Error("before와 after는 0보다 커야 해요");
  return [roundHalfUp(((before - after) / before) * 100, 1), roundHalfUp(before / after, 1)];
}

const BASE = measure(Y); // 레거시 그대로 한 번 실행

const slowestStage = (): string => Object.entries(BASE.stages).reduce((a, b) => (b[1] > a[1] ? b : a))[0];
const k1OnlySpeedup = (): number => roundHalfUp(BASE.sec / measure(Y, ["K1"]).sec, 1);
const legacyUtteranceLines = (): number => buildPromptsSlow(REF).reduce((n, p) => n + p.split("\n").filter((ln) => ln.startsWith("- ")).length, 0);

function rememberRuns(): number {
  let runs = 0;
  const w = remember((y: Float64Array) => {
    runs += 1;
    return y.length;
  });
  w(Float64Array.from([1, 2, 3]));
  w(Float64Array.from([1, 2, 3])); // 내용이 같은 소리
  return runs;
}

function int8CerChange(): string {
  const old = BASE.cer;
  const now = measure(Y, ["K3"]).cer; // 같은 서비스에서 fp32 → int8(K3)만 바뀜
  if (now < old) return "줄었다";
  if (now === old) return "같다";
  return now - old <= 0.02 ? "조금 올랐다" : "많이 올랐다";
}

const QUIZ: [string, unknown, () => unknown][] = [
  ["Q1. 레거시에서 가장 오래 걸린 단계는?", "모델 올리기", slowestStage],
  ["Q2. 레거시는 받아쓰기 모델을 몇 번 올리나?", 28, () => BASE.loads],
  ["Q3. 비중 50%인 단계를 2배 빠르게 하면 전체는 몇 배? (소수 둘째 자리)", 1.33, () => roundHalfUp(amdahl(0.5, 2), 2)],
  ["Q4. 이중 반복문(구간 찾기)만 고치면 전체는 몇 배 빨라지나? (소수 첫째 자리)", 1.0, k1OnlySpeedup],
  ["Q5. 레거시는 발언 14개를 LLM에 보낼 때 발언 줄을 모두 몇 줄 보내나?", 105, legacyUtteranceLines],
  ["Q6. 내용이 같은 소리를 두 번 주면, remember로 감싼 느린 함수는 몇 번 실행되나?", 1, rememberRuns],
  ["Q7. 60초가 15초가 되면 (줄어든 비율 %, 빨라진 배수)는?", [75.0, 4.0], () => saved(60, 15)],
  ["Q8. 작은 모델(int8)로 바꾼 뒤 글자 오류율은? (줄었다 / 같다 / 조금 올랐다)", "조금 올랐다", int8CerChange],
];
let score = 0;
for (const [q, want, compute] of QUIZ) {
  const got = compute();
  const ok = same(got, want);
  score += Number(ok);
  console.log(`${ok ? "O" : "X"} ${q}  → ${Array.isArray(got) ? JSON.stringify(got) : got}`);
}
console.log(`정리 퀴즈 ${score} / ${QUIZ.length}`);
check(QUIZ.length === 8 && score === 8, "퀴즈 8문항의 정답이 코드를 돌려 얻은 값과 모두 같아야 해요.");
